import random, itertools, collections, time
n=21
subs5=list(itertools.combinations(range(n),5))
remsets=[]
for k in range(4):
    remsets += list(itertools.combinations(range(n),k))

def alpha_le4(adj):
    # no independent set 5
    for S in subs5:
        ok=True
        for i in range(5):
            ai=adj[S[i]]
            for j in range(i+1,5):
                if (ai>>S[j])&1:
                    ok=False; break
            if not ok: break
        if ok:
            return False,S
    return True,None

def connected_after_removals(adj):
    V=set(range(n))
    for R in remsets:
        rem=set(R)
        avail=[v for v in range(n) if v not in rem]
        if not avail: continue
        start=avail[0]
        seen={start}
        stack=[start]
        while stack:
            v=stack.pop()
            m=adj[v]
            for w in avail:
                if w not in seen and ((m>>w)&1):
                    seen.add(w); stack.append(w)
        if len(seen)<len(avail): return False,R,avail,set(avail)-seen
    return True,None,None,None

def conn_ge4(adj):
    return connected_after_removals(adj)[0]

for p in [0.55,0.6,0.65,0.7,0.5]:
